    group_list = []
    for char in paren_string:
        if char == '(':
            open_brace_count += 1
        elif char == ')':
            close_brace_count += 1
        if open_brace_count == close_brace_count:
            group_list.append(current_group)
            current_group = ""
            open_brace_count = 0
            close_brace_count = 0
        current_group += char
