def verify_isbn(isbn: str) -> str:
    isbn_sum = 0
    for i, digit in enumerate(isbn[:-1]):
        if digit == 'X':
            digit = 10
        isbn_sum += (i + 1) * int(digit)
    expected_checksum = 11 - isbn_sum % 11
    if expected_checksum == 10:
        expected_checksum = 'X'
    if isbn[-1] == expected_checksum:
        return "Right"
    else:
        return isbn[:-1] + expected_checksum

def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a dictionary to store the number of chatting pairs that can be separated by adding an aisle
    # at each possible position
    aisle_positions = {}
    for i in range(1, M+1):
        for j in range(1, N+1):
            aisle_positions[(i, j)] = 0

    # Count the number of chatting pairs that can be separated by adding an aisle at each possible position
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        for i in range(1, M+1):
            for j in range(1, N+1):
                if (x1 <= i <= x2 and y1 <= j <= y2) or (x1 >= i >= x2 and y1 >= j >= y2):
                    aisle_positions[(i, j)] += 1

    # Select the most effective positions for aisles, aiming to separate as many chatting pairs as possible
    optimal_positions = []
    while len(optimal_positions) < K + L:
        max_value = max(aisle_positions.values())
        for position, value in aisle_positions.items():
            if value == max_value:
                optimal_positions.append(position)
                break
        for position in optimal_positions:
