def count_passing_ways(n, m):
    dp = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
        dp[i][1] = i + 1
    for j in range(2, m + 1):
        for i in range(n):
            if i == 0:
                dp[i][j] = dp[n - 1][j - 1]
            else:
                dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1]
    return dp[n - 1][m]

def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        mapping[encoded[i]] = original[i]

    # Check for contradictions in the mapping
    for i in range(len(encoded)):
        if encoded[i] in mapping and mapping[encoded[i]] != original[i]:
            return "Failed"

    # Decode the message using the mapping
    decoded = ""
    for i in range(len(message)):
        if message[i] in mapping:
            decoded += mapping[message[i]]
        else:
            decoded += message[i]

    return decoded

def count_partitions(n, k, x):
    # Initialize a 2D array to store the results
    # The number of rows is k and the number of columns is n+1
    dp = [[0 for _ in range(n+1)] for _ in range(k+1)]

    # Initialize the first column of the array
    for i in range(k+1):
        dp[i][0] = 1

    # Fill in the table
