def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num in [2, 3]:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    for i in range(5, int(num ** 0.5) + 1):
        if num % i == 0 or num % (i + 2) == 0:
            return False
    return True

def generate_numbers(n, rules):
    # Create a queue to perform BFS
    queue = [(n, 0)] # (number, level)
    # Create a set to store unique numbers
    unique_numbers = set()
    # Perform BFS
    while queue:
        number, level = queue.pop(0)
        # If the number is unique, add it to the set
        if number not in unique_numbers:
            unique_numbers.add(number)
        # If the level is less than the number of digits, transform the number
        if level < len(str(n)):
            for rule in rules:
                new_number = number
                for i in range(10):
                    if i == rule[0]:
                        new_number = new_number.replace(str(i), str(rule[1]))
                queue.append((new_number, level + 1))
    return len(unique_numbers)

