def next_permutation(perm: list) -> bool:
    # Find the first number from the end that is smaller than the number following it
    for i in range(len(perm) - 1, 0, -1):
        if perm[i - 1] < perm[i]:
            # Swap it with the smallest number that is larger and comes after it
            smallest_larger_index = i
            for j in range(i + 1, len(perm)):
                if perm[j] > perm[i - 1] and perm[j] < perm[smallest_larger_index]:
                    smallest_larger_index = j
            perm[i - 1], perm[smallest_larger_index] = perm[smallest_larger_index], perm[i - 1]

            # Reverse the order of numbers after the original first smaller number
            perm[i:] = reversed(perm[i:])
            return True

    # If the input is the last permutation (in descending order), return False
    return False

def jinjin_savings_plan(budgets: List[int]) -> int:
    # Calculate the total amount of money saved each month
    total_saved = 0
    for i, budget in enumerate(budgets, 1):
        # If the budget is less than or equal to 100, there is nothing to save
        if budget <= 100:
            continue
        # Calculate the amount saved and add it to the total saved
        amount_saved = min(budget - 100, 2 * (i % 2))
        total_saved += amount_saved

    # Calculate the total amount of money Jinjin will have at the end of the year
    total_amount = total_saved * (1 + 0.2) ** 12

    # If the total amount is negative, return the negative value of the month it went negative in
    if total_amount < 0:
        return -1 * (i % 2)
    else:
        return total_amount

def minimum_students_to_leave(heights):
    # Check if the list is empty
    if not heights:
        return 0

    # Initialize variables
    min_students = 0
    current_height = heights[0]

    # Iterate over the list and keep track of the minimum height
    for i in range(1, len(heights)):
        if heights[i] < current_height:
            min_students += 1
            current_height = heights[i]

    return min_students

def min_groups(w, n, prices):
    groups = []
    for i in range(n):
        group = [i]
        for j in range(i+1, n):
            if prices[i] + prices[j] <= w:
                group.append(j)
        groups.append(group)
    return len(groups)

